from odoo import fields, models

class Static(models.Model):
    _name = 'dy.probe.static'
    value = fields.Char(string='静态对照')

    def read_value(self):
        return self.value

    def missing_model(self):
        return self.env['dy.probe.absent']

    def duplicate_model(self):
        return self.env['dy.probe.duplicate']

    def missing_dependency_model(self):
        return self.env['dy.probe.missing']

